uint32 TiffEntry::getU32(uint32 index) const {
  if (type == TIFF_SHORT)
    return getU16(index);

  switch (type) {
  case TIFF_LONG:
  case TIFF_OFFSET:
  case TIFF_BYTE:
  case TIFF_UNDEFINED:
  case TIFF_RATIONAL:
  case TIFF_SRATIONAL:
    break;
  default:
    ThrowTPE("Wrong type %u encountered. Expected Long, Offset, Rational or "
             "Undefined on 0x%x",
             type, tag);
  }

  return data.peek<uint32>(index);
}

